 import React, { useState } from 'react';
import './AnswerForm.css';
import { postAnswer } from '../../services/api';

function AnswerForm({ questionId, onAnswerSubmitted }) {
  const [text, setText] = useState('');
  const [image, setImage] = useState(null);
  const userId = localStorage.getItem('userId');

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append('text', text);
    formData.append('questionId', questionId);
    formData.append('userId', userId);
    if (image) formData.append('image', image);

    try {
      const data = await postAnswer(formData);
      onAnswerSubmitted(data);
      setText('');
      setImage(null);
    } catch (error) {
      alert('A apărut o eroare la trimiterea răspunsului.');
      console.error('Eroare postAnswer:', error);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="answer-form" encType="multipart/form-data">
      <textarea
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Scrie un răspuns..."
      />
      <input
        type="file"
        accept="image/*"
        onChange={(e) => setImage(e.target.files[0])}
      />
      <button type="submit">Trimite răspuns</button>
    </form>
  );
}

export default AnswerForm;
